<?php
defined('ABSPATH') || exit;
/** Consolidates prior unpaid production jobs under the accepted aggregate quote without adding their old totals. */
final class GE_Work_History_Components {
    const META='_ge_historical_component_sources';
    private static function pending_evidence($order){
        if($order->get_meta('_ge_payment_state',true)==='receipt_uploaded' || $order->get_meta('_ge_payment_receipt_uploaded_at',true))return true;$docs=GE_WTP_Documents::get_documents($order->get_id());GE_Work_History_Storage::check();foreach($docs as $doc)if(in_array($doc['category']??'',array('comprobante','recibo'),true))return true;return false;
    }
    public static function prepare($quote,$ids){
        if(!$ids)return array();$ids=array_values(array_unique(array_map('absint',$ids)));sort($ids,SORT_NUMERIC);if(count($ids)>50 || count($quote['snapshot']['items'])!==1)throw new DomainException('La consolidación requiere un único renglón agregado y hasta 50 trabajos.');$base=reset($quote['snapshot']['items']);$qty=(int)$base['quantity'];if($qty<=0 || (float)$base['quantity']!== (float)$qty)throw new DomainException('Revisá la cantidad del presupuesto agregado.');$out=array();$sum=0;
        foreach($ids as $id){$o=GE_Work_Finance::order($id);GE_Work_History_Storage::check();if(is_wp_error($o))throw new DomainException($o->get_error_message());$o->read_meta_data(true);GE_Work_History_Storage::check();if($o->get_customer_id()!==(int)$quote['customer_id'] || $o->get_currency()!==($quote['snapshot']['currency']??'ARS') || in_array($o->get_status(),array('cancelled','failed','refunded'),true) || $o->get_meta('_ge_financial_parent_order_id',true) || $o->get_meta('_ge_work_order',true)==='yes' || $o->get_date_paid() || $o->get_transaction_id() || $o->get_meta(GE_Work_Finance::META,true) || $o->get_meta(GE_Work_Finance::HISTORICAL_META,true) || $o->get_meta('_ge_commercial_credited_attempts',true) || GE_Work_Finance::pending_attempt($o) || self::pending_evidence($o) || !in_array($o->get_payment_method(),array('','bacs','cod'),true))throw new DomainException('Un trabajo ya tiene vínculos o cobros; no se moverá dinero.');$receiver=GE_WTP_Quote_Billing_Control::receiver($quote['snapshot']);$old_receiver=(array)$o->get_meta('_ge_billing_profile_snapshot',true);if(!empty($receiver['cuit']) && !empty($old_receiver['cuit']) && preg_replace('/\D/','',$receiver['cuit'])!==preg_replace('/\D/','',$old_receiver['cuit']))throw new DomainException('Los receptores fiscales no coinciden.');$old_company=$o->get_billing_company();if($old_company && !empty($receiver['legal_name']) && preg_replace('/[^\pL\pN]/u','',mb_strtoupper($old_company))!==preg_replace('/[^\pL\pN]/u','',mb_strtoupper($receiver['legal_name'])))throw new DomainException('Revisá el receptor fiscal de los trabajos.');$balance=GE_Work_Finance::balance($o);GE_Work_History_Storage::check();if(is_wp_error($balance)||$balance['amount_paid_cents']!==0)throw new DomainException('Revisá los cobros previos antes de consolidar.');$nested=wc_get_orders(array('limit'=>1,'meta_key'=>'_ge_source_quote_order_id','meta_value'=>$id));GE_Work_History_Storage::check();if($nested)throw new DomainException('Un trabajo tiene órdenes vinculadas; requiere revisión individual.');$count=0;foreach($o->get_items() as $item){$n=(int)$item->get_quantity();if($n<=0 || (float)$item->get_quantity()!==(float)$n || $item->get_meta('_ge_item_status',true)==='cancelled')throw new DomainException('Revisá los renglones del trabajo.');$count+=$n;}if(!$count)throw new DomainException('El trabajo no tiene renglones.');$sum+=$count;$out[$id]=array('order_id'=>$id,'number'=>$o->get_order_number(),'quantity'=>$count,'before'=>GE_Work_Historical_Reconciliation::snapshot($o));}
        if($sum!==$qty)throw new DomainException('La cantidad de los trabajos no coincide con el presupuesto consolidado.');return $out;
    }
    public static function lines($snapshot,$components){
        if(!$components)return $snapshot['items'];$base=reset($snapshot['items']);$qty=(int)$base['quantity'];$out=array();$allocated_net=0;$allocated_base=0;$allocated_tax=0;$index=0;$count=count($components);
        foreach($components as $id=>$component){$last=++$index===$count;$n=$component['quantity'];$line=$base;$line['quantity']=$n;$line['name']=$base['name'].' · Trabajo #'.$component['number'];$line['net_cents']=$last?$base['net_cents']-$allocated_net:intdiv($base['net_cents']*$n,$qty);$taxable=(int)($base['taxable_base_cents']??$base['net_cents']);$line['taxable_base_cents']=$last?$taxable-$allocated_base:intdiv($taxable*$n,$qty);$tax=(int)($base['tax_cents']??$snapshot['tax_cents']);$line['tax_cents']=$last?$tax-$allocated_tax:intdiv($tax*$n,$qty);$line['_historical_component_order_id']=$id;$allocated_net+=$line['net_cents'];$allocated_base+=$line['taxable_base_cents'];$allocated_tax+=$line['tax_cents'];$out[]=$line;}return $out;
    }
    public static function render($quote,$source){
        if(count($quote['snapshot']['items']??array())!==1 || $source['row']['production']!=='completed')return;$orders=wc_get_orders(array('customer_id'=>$quote['customer_id'],'limit'=>100,'orderby'=>'ID','order'=>'DESC'));$options=array();foreach($orders as $o){if($o->get_meta('_ge_work_order',true)==='yes' || $o->get_meta('_ge_financial_parent_order_id',true) || $o->get_meta('_ge_commercial_payment_order',true)==='yes' || in_array($o->get_status(),array('cancelled','failed','refunded'),true) || $o->get_date_paid() || $o->get_meta(GE_Work_Finance::META,true) || $o->get_meta(GE_Work_Finance::HISTORICAL_META,true))continue;$b=GE_Work_Finance::balance($o);if(is_wp_error($b)||$b['amount_paid_cents'])continue;$names=array();foreach($o->get_items() as $i)$names[]=$i->get_name().' × '.$i->get_quantity();if($names)$options[$o->get_id()]='#'.$o->get_order_number().' · '.implode(' · ',$names);}if(!$options)return;
        echo '<details><summary>Incluir trabajos anteriores en una única factura (opcional)</summary><p>Seleccioná únicamente los trabajos incluidos en este presupuesto final. Sus importes anteriores se conservarán como referencia y no se sumarán como otras ventas. Los trabajos con cobros previos requieren revisión.</p>';foreach($options as $id=>$label)echo '<label><input type="checkbox" name="component_ids[]" value="'.absint($id).'"> '.esc_html($label).'</label>';echo '</details>';
    }
    public static function attach($parent,$components){
        if(!$components)return;$map=array();foreach($parent->get_items() as $item){$id=absint($item->get_meta('_ge_historical_component_order_id',true));if($id)$map[$id]=$item;}if(count($map)!==count($components))throw new RuntimeException('No se verificó el vínculo de todos los trabajos.');
        foreach($components as $id=>$data){$o=GE_Work_Finance::strict_order($id);$o->read_meta_data(true);GE_Work_History_Storage::check();if(GE_Work_Historical_Reconciliation::hash(GE_Work_Historical_Reconciliation::snapshot($o))!==GE_Work_Historical_Reconciliation::hash($data['before']))throw new DomainException('Un trabajo cambió durante la consolidación.');$o->update_meta_data('_ge_work_order','yes');$o->update_meta_data('_ge_source_quote_order_id',$parent->get_id());$o->update_meta_data('_ge_source_quote_item_id',$map[$id]->get_id());$o->update_meta_data('_ge_financial_parent_order_id',$parent->get_id());GE_Work_History_Storage::save_order_meta($o);GE_Work_History_Storage::check();$map[$id]->update_meta_data('_ge_work_order_id',$id);$map[$id]->save_meta_data();GE_Work_History_Storage::check();GE_Work_Finance::clear_order_cache($id);}
        $parent->update_meta_data(self::META,array('components'=>$components,'actor'=>get_current_user_id(),'recorded_at'=>gmdate('c')));GE_Work_History_Storage::save_order_meta($parent);GE_Work_History_Storage::check();
    }
}

require_once __DIR__.'/history-consolidation.php';
